\centering
\begin{subfigure}[b]{0.48\linewidth}
\includegraphics[width=\linewidth]{figures/paper/fig_degradation_curve.pdf}
\caption{Token pruning across connector classes.}
\label{fig:degradation_curve}
\end{subfigure}
\hfill
\begin{subfigure}[b]{0.48\linewidth}
